{
  "name": "@unown/ostinato",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "description": "Keyboard-first, offline-first spaced-repetition flashcard PWA (vanilla TS, zero dependencies)."
}
/**
 * Ostinato domain types — pure, serializable, DOM-free.
 *
 * Single source of truth for the app's data model (the Coda `types.ts`
 * precedent). Every entity is plain JSON (no class instances, no
 * Date objects) so a store serializing to JSON is a lossless,
 * non-rewrite path to import/export (P0 #7: JSON round-trip lossless).
 */

/**
 * A flashcard. `front`/`back` are markdown source (P0 #1: markdown
 * front/back). SM-2 scheduling state is carried per-card; a card that
 * has never been reviewed carries no `sm2` field.
 */
export type Card = {
  id: string;
  /** the deck this card belongs to; must match a Deck.id present in the store */
  deckId: string;
  front: string;
  back: string;
  /**
   * SM-2 scheduling state (O-2 implements the scheduler; O-1 pins the
   * shape only). All timestamps ISO-8601; `interval` is in days
   * (floating point is not a defect — SM-2's 2^0/2^1/… ease curve
   * yields fractional intervals under `easiness` drift).
   */
  sm2?: {
    /** repetitions since last `again` (0-based) */
    repetitions: number;
    /** current ease factor, ≥ 1.3 in SM-2 */
/**
 * Id generation — pure, no `crypto` import (the boundary test's
 * NODE_BUILTINS gate: `node:crypto` would fail the import scan even
 * in a test file).
 *
 * Coda precedent: the domain keeps ids as plain strings; generation is
 * injected at the edge so the core stays deterministic. `newUniqueId`
 * mixes a base-36 time prefix with 21 random bits (53 - 32) and
 * validates uniqueness against the current sets — the caller retries on
 * the astronomically-unlikely collision.
 */

/** Build the base-36 timestamp prefix shared with Coda's id scheme. */
function timePrefix(): string {
  return Date.now().toString(36);
}

/**
 * Draw 21 random bits from `Math.random()` (the only randomness source
 * the domain is allowed to touch — it is a global, not a module import,
 * and is never called on the scheduler's deterministic path).
 */
function randomTail(): string {
  let n = Math.floor(Math.random() * 0x1000000); // 24 bits, trimmed below
  const bits = (n & 0x1fffff).toString(36); // 21 bits → up to 5 chars
  return bits.padStart(5, "0");
}

/**
 * Generate a card, deck, or review id that is not already present.
 * Retry on collision (max 32 attempts — enough for any realistic set
 * size given 2^21 random space per time tick; throws
 * DomainInvariantError so the caller gets a guard failure, not an
 * infinite loop).
 *
 * `prefix` keeps ids readable (`card_…` / `deck_…` / `review_…`).
 */
export function newUniqueId(
  prefix: "card" | "deck" | "review",
  taken: ReadonlySet<string>,
): string {
  const base = timePrefix();
  for (let attempt = 0; attempt < 32; attempt++) {
    const id = `${prefix}_${base}_${randomTail()}`;
    if (!taken.has(id)) return id;
  }
  // Unreachable in practice (birthday bound: 32 draws into 2^21);
  // surface as a guard failure rather than loop.
  throw new Error(`newUniqueId: 32 collisions for prefix ${prefix}`);
}

/**
 * Import/Export port — P0 #7 (JSON round-trip lossless, byte-stable).
 *
 * The implementation is pinned at O-2 by `io.test.ts` (the Lane A
 * suite). Matrix lane I-1: same data, two sequential boots →
 * identical export bytes. The contract:
 *
 * - `exportData`: canonical JSON — key-sorted objects, stable array
 *   order (the deck's `cardOrder` is the array-of-card-ids order,
 *   not re-sorted), no trailing newline. Byte-stable across boots.
 * - `importData`: parse → `assertData` → throw `DomainInvariantError`
 *   on ANY invariant breach (orphan card, cardOrder mismatch, unknown
 *   top-level fields, duplicate ids, …). A corrupted or foreign JSON
 *   document must NEVER pass through silently.
 */
import type { OstinatoData, ImportExportPort, ReviewEvent, DeckSettings } from "./types.js";
import { DomainInvariantError } from "./types.js";
import { assertData } from "./invariants.js";

/** Top-level keys that are ALLOWED in an import document. */
const ALLOWED_TOP = new Set(["decks", "cards", "reviews"]);

/**
 * Deep-clone a plain-JSON value (the data set is plain JSON at every
 * level — no class instances — so `JSON.parse(JSON.stringify(v))` is
 * the identity map, and no key-sorting is needed to clone).
 */
function clone<T>(v: T): T {
  return JSON.parse(JSON.stringify(v)) as T;
}

/**
 * Recursively sort object keys (depth-first) and produce a
 * deterministic key order. Arrays keep their index order (the
 * deck's cardOrder is the semantic array order — it must NOT be
 * sorted, only its contents are canonically ordered by the domain).
 *
 * This is the "byte-stable" requirement: two identical data sets
 * always serialize to the same bytes, regardless of key insertion
 * order (which `JSON.parse` from a user document does not
 * guarantee).
 */
function sortKeysDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortKeysDeep);
  }
  if (value !== null && typeof value === "object") {
    const out: Record<string, unknown> = {};
    const keys = Object.keys(value as Record<string, unknown>).sort();
    for (const k of keys) {
      out[k] = sortKeysDeep((value as Record<string, unknown>)[k]);
    }
    return out;
  }
  return value;
}

/**
 * Serialize to canonical JSON: sorted object keys, compact separators
 * (no whitespace — the wire format is machine-readable, not
 * human-pretty; the UI shell's export UI can pretty-print at the
 * edge without affecting byte-stability of the data layer).
 */
export function toCanonicalJson(data: OstinatoData): string {
  const sorted = sortKeysDeep(clone(data));
  return JSON.stringify(sorted);
}

/**
 * The ImportExportPort implementation.
 *
 * `exportData` is a pure function of the data set — byte-stable
 * across boots. `importData` validates every invariant before
 * returning the data.
 */
export function createImportExport(): ImportExportPort {
  return {
    /**
     * Serialize to canonical, byte-stable JSON.
     * Same data set → same bytes, every boot.
     */
    exportData(data: OstinatoData): string {
      return toCanonicalJson(data);
    },

    /**
     * Parse + validate a JSON document.
     *
     * @throws {DomainInvariantError} on:
     *  - not valid JSON
     *  - root is not a plain object
     *  - unknown top-level keys (ALLOWED_TOP only: `decks`, `cards`, `reviews`)
     *  - `decks` or `cards` not an array
     *  - `reviews` present but not an array (a pre-log document omits it and imports clean as `reviews: []`)
     *  - any `assertData` invariant breach
     *  - duplicate card or deck or review ids (assertData catches this)
     *  - orphan card (assertData catches this)
     *  - cardOrder set-mismatch (assertData catches this)
     *  - review log entries with unknown card/deck ids or grade outside 1..4 (assertData catches this)
     */
    importData(json: string): OstinatoData {
      let parsed: unknown;
      try {
        parsed = JSON.parse(json);
      } catch {
        throw new DomainInvariantError("import: not valid JSON");
      }

      // Root must be a plain object.
      if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
        throw new DomainInvariantError(
          "import: root must be a plain object with 'decks' and 'cards'",
        );
      }

      const root = parsed as Record<string, unknown>;

      // Unknown top-level keys are rejected (a future field added by a
      // newer app version is NOT silently swallowed — it must be
      // explicitly handled in importData, not just appear in the data).
      for (const key of Object.keys(root)) {
        if (!ALLOWED_TOP.has(key)) {
          throw new DomainInvariantError(`import: unknown top-level key: '${key}'`);
        }
      }

      // Both keys must be present.
      if (!Array.isArray(root.decks)) {
        throw new DomainInvariantError("import: 'decks' must be an array");
      }
      if (!Array.isArray(root.cards)) {
        throw new DomainInvariantError("import: 'cards' must be an array");
      }

      // Backward compat (R-1): pre-log documents import clean — the
      // absent key becomes an empty review log, never an error.
      if (root.reviews !== undefined && !Array.isArray(root.reviews)) {
        throw new DomainInvariantError("import: 'reviews' must be an array");
      }

      const data = {
        ...parsed,
        reviews: Array.isArray(root.reviews) ? (root.reviews as ReviewEvent[]) : [],
      } as OstinatoData;

      // Per-card field checks: front/back must be strings.
      for (const card of data.cards) {
        if (typeof card !== "object" || card === null) {
          throw new DomainInvariantError("import: card entry must be an object");
        }
        if (typeof card.id !== "string") {
          throw new DomainInvariantError(`import: card.id must be a string (got ${typeof card.id})`);
        }
        if (typeof card.deckId !== "string") {
          throw new DomainInvariantError(`import: card.deckId must be a string`);
        }
        if (typeof card.front !== "string") {
          throw new DomainInvariantError(`import: card ${card.id}: front must be a string`);
        }
        if (typeof card.back !== "string") {
          throw new DomainInvariantError(`import: card ${card.id}: back must be a string`);
        }
        // sm2 is optional; if present, shape-check it.
        if (card.sm2 !== undefined && card.sm2 !== null) {
          const sm2 = card.sm2;
          if (typeof sm2.repetitions !== "number" || sm2.repetitions < 0) {
            throw new DomainInvariantError(`import: card ${card.id}: sm2.repetitions must be a non-negative number`);
          }
          if (typeof sm2.easiness !== "number" || sm2.easiness < 1.3) {
            throw new DomainInvariantError(`import: card ${card.id}: sm2.easiness must be a number >= 1.3`);
          }
          if (typeof sm2.interval !== "number" || sm2.interval <= 0) {
            throw new DomainInvariantError(`import: card ${card.id}: sm2.interval must be a positive number`);
          }
        }
      }

      // Per-deck field checks.
      for (const deck of data.decks) {
        if (typeof deck !== "object" || deck === null) {
          throw new DomainInvariantError("import: deck entry must be an object");
        }
        if (typeof deck.id !== "string") {
          throw new DomainInvariantError(`import: deck.id must be a string (got ${typeof deck.id})`);
        }
        if (typeof deck.name !== "string" || deck.name.length === 0) {
          throw new DomainInvariantError(`import: deck ${deck.id}: name must be a non-empty string`);
        }
        if (!Array.isArray(deck.cardOrder)) {
          throw new DomainInvariantError(`import: deck ${deck.id}: cardOrder must be an array`);
        }
        for (const id of deck.cardOrder) {
          if (typeof id !== "string") {
            throw new DomainInvariantError(`import: deck ${deck.id}: cardOrder entries must be strings`);
          }
        }
        // R-2 deck settings: absent = clean (backward compat), `{}` = clean,
        // a present field must be an integer >= 0.
        if (deck.settings !== undefined && deck.settings !== null) {
          const s = deck.settings as unknown as DeckSettings;
          if (typeof s !== "object" || Array.isArray(s)) {
            throw new DomainInvariantError(`import: deck ${deck.id}: settings must be an object`);
          }
          const n = s.newCardsPerSession;
          if (n !== undefined) {
            if (typeof n !== "number" || !Number.isInteger(n) || n < 0) {
              throw new DomainInvariantError(`import: deck ${deck.id}: settings.newCardsPerSession must be an integer >= 0`);
            }
          }
        }
      }

      // Per-review field checks (R-1 review log entries).
      for (const review of data.reviews) {
        if (typeof review !== "object" || review === null) {
          throw new DomainInvariantError("import: review entry must be an object");
        }
        if (typeof review.id !== "string") {
          throw new DomainInvariantError(`import: review.id must be a string (got ${typeof review.id})`);
        }
        if (typeof review.cardId !== "string") {
          throw new DomainInvariantError(`import: review ${review.id}: cardId must be a string`);
        }
        if (typeof review.deckId !== "string") {
          throw new DomainInvariantError(`import: review ${review.id}: deckId must be a string`);
        }
        if (review.grade !== 1 && review.grade !== 2 && review.grade !== 3 && review.grade !== 4) {
          throw new DomainInvariantError(`import: review ${review.id}: grade must be 1..4`);
        }
        if (typeof review.reviewedAt !== "string") {
          throw new DomainInvariantError(`import: review ${review.id}: reviewedAt must be a string`);
        }
      }

      // Full shape invariants (orphan cards, cardOrder set-match,
      // duplicate ids, review log refs, …).
      assertData(data);

      return data;
    },
  };
}

/** Convenience: the singleton port (the app uses one instance). */
export const importExport: ImportExportPort = createImportExport();

/**
 * Ostinato domain core — DOM-free invariant checks (P0 #1).
 *
 * The skeleton's only executable domain code: a small `assertData`
 * guard that validates the shape invariants of an `OstinatoData` (the
 * cardOrder set-match, no orphan cards, id uniqueness). O-2 adds the
 * scheduler; O-3 adds the repository + atomic persistence. Kept
 * deliberately tiny at O-1 so the Lane A test boot has a real
 * assertion target without touching SM-2 logic (non-overlap: O-2).
 */
import type { OstinatoData } from "./types.js";
import { DomainInvariantError } from "./types.js";

/**
 * Assert `data` satisfies OstinatoData's invariants:
 *  - no duplicate deck ids / card ids
 *  - every card's `deckId` references an existing deck
 *  - every deck's `cardOrder` set-matches its cards exactly
 *     (the Coda Board.taskOrder invariant, per-deck)
 *  - card front/back are strings (markdown source, may be empty —
 *    an empty-front card is a user's choice, not an invariant breach)
 *  - R-1 review log (append-only activity log): every review id is
 *    unique; every `cardId` resolves to a card; every `deckId`
 *    resolves AND matches the card's own `deckId`; `grade` is 1..4;
 *    `reviewedAt` is a string
 *
 * @throws {DomainInvariantError} on the first breach
 */
export function assertData(data: OstinatoData): void {
  const deckIds = new Set<string>();
  for (const deck of data.decks) {
    if (deckIds.has(deck.id)) throw new DomainInvariantError(`duplicate deck id: ${deck.id}`);
    deckIds.add(deck.id);
  }

  const cardIds = new Set<string>();
  const cardsByDeck = new Map<string, Set<string>>();
  for (const card of data.cards) {
    if (cardIds.has(card.id)) throw new DomainInvariantError(`duplicate card id: ${card.id}`);
    cardIds.add(card.id);
    if (!deckIds.has(card.deckId)) throw new DomainInvariantError(`orphan card ${card.id}: unknown deck ${card.deckId}`);
    if (typeof card.front !== "string" || typeof card.back !== "string") {
      throw new DomainInvariantError(`card ${card.id}: front/back must be strings`);
    }
    let bucket = cardsByDeck.get(card.deckId);
    if (!bucket) {
      bucket = new Set();
      cardsByDeck.set(card.deckId, bucket);
    }
    bucket.add(card.id);
  }

  for (const deck of data.decks) {
    const seenInOrder = new Set(deck.cardOrder);
    if (seenInOrder.size !== deck.cardOrder.length) {
      throw new DomainInvariantError(`deck ${deck.id}: duplicate cardOrder entry`);
    }
    const owned = cardsByDeck.get(deck.id) ?? new Set<string>();
    for (const id of owned) {
      if (!seenInOrder.has(id)) throw new DomainInvariantError(`deck ${deck.id}: card ${id} missing from cardOrder`);
    }
    for (const id of seenInOrder) {
      if (!owned.has(id)) throw new DomainInvariantError(`deck ${deck.id}: cardOrder lists unknown card ${id}`);
    }
  }

  // R-1 review log invariants (the append-only activity log).
  const reviewIds = new Set<string>();
  for (const event of data.reviews) {
    if (reviewIds.has(event.id)) throw new DomainInvariantError(`duplicate review id: ${event.id}`);
    reviewIds.add(event.id);
    if (!cardIds.has(event.cardId)) throw new DomainInvariantError(`review ${event.id}: unknown card ${event.cardId}`);
    const card = data.cards.find((c) => c.id === event.cardId)!;
    if (event.deckId !== card.deckId) throw new DomainInvariantError(`review ${event.id}: deck ${event.deckId} does not match card's deck ${card.deckId}`);
    if (event.grade !== 1 && event.grade !== 2 && event.grade !== 3 && event.grade !== 4) throw new DomainInvariantError(`review ${event.id}: grade must be 1..4`);
    if (typeof event.reviewedAt !== "string") throw new DomainInvariantError(`review ${event.id}: reviewedAt must be a string`);
  }
}

/**
 * localStorage + atomic-writes adapter — the HOST edge (O-2 storage
 * decision; contract in `src/domain/storage.ts`).
 *
 * LIVES OUTSIDE `src/domain/` on purpose: the boundary test bans
 * `localStorage.` references in domain modules. This file is host
 * code (like the UI shell) that implements the domain's `StoragePort`
 * over the host's `StorageLike` (e.g. `window.localStorage`).
 *
 * Atomicity: `save` writes the temp key first, then the commit key;
 * a crash between the two leaves an orphaned temp that `recover`
 * discards on boot. The committed key always holds the last complete
 * state.
 */
import type { OstinatoData, } from "../domain/types.js";
import type { StoragePort, StorageLike } from "../domain/storage.js";

/** Canonical committed key + atomic temp key (the app's namespace). */
export const STORAGE_KEY = "ostinato.data";
export const STORAGE_TMP_KEY = "ostinato.tmp";

/**
 * Create a `StoragePort` backed by a `StorageLike` (the UI edge passes
 * `window.localStorage`). See `src/domain/storage.ts` for the design
 * receipt (localStorage + atomic-writes, not IndexedDB).
 */
export function createLocalStorageAdapter(storage: StorageLike): StoragePort {
  return {
    async load(): Promise<OstinatoData | null> {
      const raw = storage.getItem(STORAGE_KEY);
      if (raw === null) return null;
      try {
        return JSON.parse(raw) as OstinatoData;
      } catch {
        // Undecodable committed bytes: surface as "no data" so the
        // boot path can run importData(io) and throw the honest
        // DomainInvariantError rather than crash on the raw parse.
        return null;
      }
    },

    async save(_data: OstinatoData, rawJson: string): Promise<void> {
      // The adapter stores EXACTLY the canonical bytes the caller
      // produced (io.exportData) — no re-encode, byte-stable by
      // construction (matrix lane I-1).
      storage.setItem(STORAGE_TMP_KEY, rawJson);
      storage.setItem(STORAGE_KEY, rawJson);
      try {
        storage.removeItem(STORAGE_TMP_KEY);
      } catch {
        // best-effort: the commit already succeeded; a failed temp
        // cleanup is harmless (recover() will tidy it next boot).
      }
    },

    async recover(): Promise<void> {
      // Orphaned temp (interrupted save) → discard. The commit key,
      // when present, is the last complete state.
      if (storage.getItem(STORAGE_TMP_KEY) !== null) {
        try {
          storage.removeItem(STORAGE_TMP_KEY);
        } catch {
          // ignore — next boot retries
        }
      }
    },
  };
}

/**
 * Deck/card construction + edit helpers (P0 #1, the finished model
 * layer).
 *
 * Every helper returns a NEW `OstinatoData` (the Coda domain-purity
 * convention — no in-place mutation of caller state) and re-runs
 * `assertData` on the result, so no mutation path can leave the store
 * in a breach state. Id generation is injected (`newUniqueId`'s
 * signature keeps the clock/randomness at the edge, so unit tests can
 * pin exact ids).
 *
 * Timestamps: `now` is an ISO-8601 string injected by the caller — the
 * domain never calls `Date.now()` on these paths (determinism is the
 * P0 #2 contract; a construction-time `now` is the one accepted
 * exception: the caller is the edge).
 */
import type { Card, Deck, DeckSettings, OstinatoData, Grade, ReviewEvent } from "./types.js";
import { DomainInvariantError } from "./types.js";
import { assertData } from "./invariants.js";
import { newUniqueId } from "./ids.js";
import { createScheduler } from "./scheduler.js";

function takenDeckIds(data: OstinatoData): Set<string> {
  const s = new Set<string>();
  for (const d of data.decks) s.add(d.id);
  return s;
}

function takenCardIds(data: OstinatoData): Set<string> {
  const s = new Set<string>();
  for (const c of data.cards) s.add(c.id);
  return s;
}

function takenReviewIds(data: OstinatoData): Set<string> {
  const s = new Set<string>();
  for (const r of data.reviews) s.add(r.id);
  return s;
}

/** Create a new deck. Returns the updated data set. */
export function createDeck(
  data: OstinatoData,
  name: string,
  now: string,
  id?: string,
): OstinatoData {
  const deckId = id ?? newUniqueId("deck", takenDeckIds(data));
  if (!id && takenDeckIds(data).has(deckId)) {
    throw new DomainInvariantError(`duplicate deck id: ${deckId}`);
  }
  if (!name || typeof name !== "string") {
    throw new DomainInvariantError("deck name must be a non-empty string");
  }
  const deck: Deck = {
    id: deckId,
    name,
    cardOrder: [],
    createdAt: now,
    updatedAt: now,
  };
  const next: OstinatoData = {
    decks: [...data.decks, deck],
    cards: data.cards,
    reviews: data.reviews,
  };
  assertData(next);
  return next;
}

/**
 * Add a card to an existing deck. `front`/`back` are markdown source
 * (may be empty — a user's choice, not a breach). Returns the updated
 * data set; the new card's id is exposed as `card.id`.
 */
export function addCard(
  data: OstinatoData,
  deckId: string,
  front: string,
  back: string,
  now: string,
  cardId?: string,
): { data: OstinatoData; card: Card } {
  const deck = data.decks.find((d) => d.id === deckId);
  if (!deck) throw new DomainInvariantError(`unknown deck: ${deckId}`);
  const cid = cardId ?? newUniqueId("card", takenCardIds(data));
  if (takenCardIds(data).has(cid)) {
    throw new DomainInvariantError(`duplicate card id: ${cid}`);
  }
  const card: Card = {
    id: cid,
    deckId,
    front,
    back,
    createdAt: now,
    updatedAt: now,
  };
  const next: OstinatoData = {
    decks: data.decks.map((d) =>
      d.id === deckId
        ? { ...d, cardOrder: [...d.cardOrder, cid], updatedAt: now }
        : d,
    ),
    cards: [...data.cards, card],
    reviews: data.reviews,
  };
  assertData(next);
  return { data: next, card };
}

/** Edit a card's front/back. Returns the updated data set. */
export function updateCard(
  data: OstinatoData,
  cardId: string,
  patch: Partial<Pick<Card, "front" | "back">>,
  now: string,
): OstinatoData {
  let found = false;
  const cards = data.cards.map((c) => {
    if (c.id !== cardId) return c;
    found = true;
    return {
      ...c,
      front: patch.front !== undefined ? patch.front : c.front,
      back: patch.back !== undefined ? patch.back : c.back,
      updatedAt: now,
    };
  });
  if (!found) throw new DomainInvariantError(`unknown card: ${cardId}`);
  const next: OstinatoData = { decks: data.decks, cards, reviews: data.reviews };
  assertData(next);
  return next;
}

/** Remove a card (and its SM-2 state) from its deck. Returns the updated data set. */
export function removeCard(data: OstinatoData, cardId: string, now: string): OstinatoData {
  const card = data.cards.find((c) => c.id === cardId);
  if (!card) throw new DomainInvariantError(`unknown card: ${cardId}`);
  const next: OstinatoData = {
    decks: data.decks.map((d) =>
      d.id === card.deckId
        ? {
            ...d,
            cardOrder: d.cardOrder.filter((id) => id !== cardId),
            updatedAt: now,
          }
        : d,
    ),
    cards: data.cards.filter((c) => c.id !== cardId),
    reviews: data.reviews,
  };
  assertData(next);
  return next;
}

/** Remove a deck and all its cards. Returns the updated data set. */
export function removeDeck(data: OstinatoData, deckId: string, now: string): OstinatoData {
  const next: OstinatoData = {
    decks: data.decks.filter((d) => d.id !== deckId),
    cards: data.cards.filter((c) => c.deckId !== deckId),
    reviews: data.reviews,
  };
  assertData(next);
  return next;
}

/**
 * Reorder a deck's cards. `order` must be the deck's current card set
 * (a permutation) — any missing or extra id throws before the mutation
 * is applied.
 */
export function reorderDeck(data: OstinatoData, deckId: string, order: string[], now: string): OstinatoData {
  const deck = data.decks.find((d) => d.id === deckId);
  if (!deck) throw new DomainInvariantError(`unknown deck: ${deckId}`);
  const current = new Set(deck.cardOrder);
  const next = new Set(order);
  if (current.size !== next.size) {
    throw new DomainInvariantError(`reorderDeck: order length ${next.size} != card set size ${current.size}`);
  }
  for (const id of order) {
    if (!current.has(id)) {
      throw new DomainInvariantError(`reorderDeck: unknown card ${id} in deck ${deckId}`);
    }
  }
  const out: OstinatoData = {
    decks: data.decks.map((d) =>
      d.id === deckId ? { ...d, cardOrder: [...order], updatedAt: now } : d,
    ),
    cards: data.cards,
    reviews: data.reviews,
  };
  assertData(out);
  return out;
}

/**
 * Apply a grade to a card via the SM-2 scheduler. Returns the updated
 * data set with the card's `sm2` state advanced AND a `ReviewEvent`
 * appended to the review log (R-1). The append rides the same
 * transition — every-transition persistence: a session killed here
 * restores the log by construction. This is the single entry point
 * from the review runner (O-3) into the scheduler.
 */
export function gradeCard(
  data: OstinatoData,
  cardId: string,
  grade: Grade,
  now: string,
): OstinatoData {
  const scheduler = createScheduler();
  let found = false;
  const cards = data.cards.map((c) => {
    if (c.id !== cardId) return c;
    found = true;
    const graded = scheduler.grade(c, grade, now);
    return graded;
  });
  if (!found) throw new DomainInvariantError(`unknown card: ${cardId}`);
  const gradedCard = data.cards.find((c) => c.id === cardId)!;
  const taken = new Set<string>([...takenReviewIds(data), ...takenCardIds(data), ...takenDeckIds(data)]);
  const event: ReviewEvent = {
    id: newUniqueId("review", taken),
    cardId: gradedCard.id,
    deckId: gradedCard.deckId,
    grade,
    reviewedAt: now,
  };
  const next: OstinatoData = { decks: data.decks, cards, reviews: [...data.reviews, event] };
  assertData(next);
  return next;
}

/**
 * Set or clear a deck's R-2 settings. `settings` is a full replacement
 * of the deck's `settings` field: pass `null` to DELETE the field
 * (the byte-stability law — a capped→uncapped deck exports pre-R-2
 * bytes, `settings` absent; `{}` is legal and also means no cap but
 * does round-trip, so the honest "uncap" write is `null`). Returns
 * the updated data set; `updatedAt` advances like every other
 * deck mutation.
 */
export function setDeckSettings(
  data: OstinatoData,
  deckId: string,
  settings: DeckSettings | null,
  now: string,
): OstinatoData {
  let found = false;
  const decks = data.decks.map((d) => {
    if (d.id !== deckId) return d;
    found = true;
    const next: Deck = { ...d, updatedAt: now };
    if (settings === null) {
      delete next.settings;
    } else {
      next.settings = settings;
    }
    return next;
  });
  if (!found) throw new DomainInvariantError(`unknown deck: ${deckId}`);
  const out: OstinatoData = { decks, cards: data.cards, reviews: data.reviews };
  assertData(out);
  return out;
}

/** Empty data set — the starting point for a new install. */
export function emptyData(): OstinatoData {
  return { decks: [], cards: [], reviews: [] };
}

/**
 * Domain-boundary test — the Coda `boundary.test.ts` precedent, ported
 * to Ostinato. Runs green in BOTH lanes:
 *
 *   Lane A — `cd apps/ostinato && bun test`: no `bunfig.toml` inside the
 *            app dir, so the root happy-dom preload does NOT apply and
 *            domain-purity is enforced against a genuinely DOM-free
 *            runtime.
 *   Lane B — `bun test apps/ostinato` from the repo root: the root
 *            `bunfig.toml`'s preload IS active (DOM globals present),
 *            so this test still runs but is masked-by-design; it
 *            remains the import-graph enforcer.
 *
 * Rule: every module under src/domain/ may import only
 *   - relative "./" imports that stay inside src/domain/ (the domain
 *     is a flat directory; "../" would escape it and is rejected)
 *   - "bun:test" (tests)
 *   - nothing Node-specific (fs/path/process/http/crypto/…)
 *   - no DOM/Node global reference (document./window./indexedDB/
 *    localStorage — the regex pins member ACCESS like
 *    `document.getElementById` or `window.localStorage`; English
 *    prose ending in the word "document." must not trip it, hence
 *    the `\w` after the dot (V-14 regex hardening))
 *   - and no self-import of a sibling module by its resolved
 *     extensionless specifier — a module importing itself creates a
 *     cycle bun reports as "escapes src/domain". Domain modules
 *     import siblings by relative specifier only (`./types.js` is
 *     valid because the scanner treats it as "stays inside the
 *     domain"); they do NOT import themselves.
 *
 * The scanner re-implements a small reader in plain JS so it survives
 * the repo's TS-unfriendly PostToolUse syntax hook (Coda precedent:
 * the boundary test uses node:fs/promises inside the TEST FILE ONLY,
 * which is explicitly allowed — tests are not domain logic).
 */
import { test, expect } from "bun:test";
// Scanner infrastructure — allowed in test files, banned from domain
// modules (the ALLOWED set below encodes that split).
// eslint-disable-next-line -- scanner infrastructure, not domain logic
import { readdir, readFile } from "node:fs/promises";

const DOMAIN_DIR = import.meta.dir;

const ALLOWED = new Set(["bun:test"]);
const NODE_BUILTINS = new Set([
  "node:fs", "fs", "node:fs/promises", "node:path", "path",
  "node:process", "process", "node:os", "os",
  "node:http", "http", "node:crypto", "crypto", "node:buffer",
  "node:stream", "stream", "node:net", "net", "node:url", "url",
  "node:util", "util",
]);
/**
 * V-14 hardening: the regex requires an identifier after the dot
 * (`\.\w`) so it pins genuine member access (`document.getElementById`,
 * `window.localStorage`) while sentence-ending prose ("…an import
 * document.") stays immune. The storage.ts comment rewording is the
 * belt; this is the braces.
 */
const DOM_GLOBS = /\b(document|window|indexedDB|localStorage|sessionStorage)\.\w/;

async function walk(dir: string): Promise<string[]> {
  const out: string[] = [];
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = `${dir}/${e.name}`;
    if (e.isDirectory()) out.push(...(await walk(p)));
    else if (e.name.endsWith(".ts")) out.push(p);
  }
  return out;
}

test("domain modules: no Node builtins, no DOM globals, closed import graph", async () => {
  const files = await walk(DOMAIN_DIR);
  const testFiles = files.filter((f) => f.endsWith(".test.ts"));
  const domainFiles = files.filter((f) => !f.endsWith(".test.ts"));

  expect(domainFiles.length).toBeGreaterThan(0); // the domain is not empty

  for (const file of domainFiles) {
    const src = await readFile(file, "utf8");

    // 1. No DOM/Node global use.
    expect(DOM_GLOBS.test(src), `${file} references a DOM/Node global`).toBe(false);

    // 2. Import scan.
    const importRe = /import\s+(?:[\s\S]*?from\s+)?["']([^"']+)["']/g;
    for (const m of src.matchAll(importRe)) {
      const spec = m[1];
      const bare = spec.replace(/\.js$/, ""); // extensionless TS import convention
      expect(NODE_BUILTINS.has(bare), `${file} imports Node builtin ${spec}`).toBe(false);
      if (!bare.startsWith(".")) {
        // bare non-relative import — must be in the allow-list
        expect(ALLOWED.has(bare), `${file} imports unapproved external ${spec}`).toBe(true);
      }
      // relative imports must stay inside the domain (flat dir: only "./")
      if (bare.startsWith("..")) {
        expect(false, `${file} escapes src/domain via ${spec}`).toBe(true);
      }
      // and no self-import (a module must not import its own specifier)
      const ownName = file.slice(DOMAIN_DIR.length + 1).replace(/\.ts$/, "");
      if (bare === ownName || bare === `./${ownName}`) {
        expect(false, `${file} self-imports ${spec}`).toBe(true);
      }
    }
  }

  // 3. Test files MAY use node:fs (scanner infra) — verify the test set
  //    is what we expect, nothing hidden.
  expect(testFiles.length).toBeGreaterThanOrEqual(1);
});

